def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty or invalid duration string")

    total_seconds = 0
    current = 0

    for char in s:
        if char.isdigit():
            current = current * 10 + int(char)
        elif char in ('h', 'm', 's'):
            if char == 'h':
                total_seconds += current * 3600
            elif char == 'm':
                total_seconds += current * 60
            elif char == 's':
                total_seconds += current
            current = 0
        else:
            raise ValueError(f"Invalid character in duration string: {char}")

    if current != 0:
        raise ValueError("Duration string must end with a unit (h, m, s)")

    return total_seconds
